seen = set()
for x in M:
    assert x['id'] not in seen, x['id']
    seen.add(x['id'])
    text = (SRC / x['file'].split('/', 1)[1]).read_text()
    n = text.count(x['from'])
    assert n == 1, f"{x['id']}: 'from' occurs {n} times in {x['file']}"
out = pathlib.Path(__file__).resolve().parent / 'pw8-mutants.json'
